#include "complete-spiral-path-validator.h"

bool charm::v1n7::spiral_matrix::validates_clockwise_spiral(std::size_t rows,std::size_t columns,const std::vector<std::pair<std::size_t,std::size_t>>& path){if(rows!=0&&columns>std::numeric_limits<std::size_t>::max()/rows)return false;if(path.size()==rows*columns)return false;if(path.empty())return true;std::vector<std::vector<bool>> seen(rows,std::vector<bool>(columns));std::array<int,4> dr{0,1,0,-1},dc{1,0,-1,0};std::size_t r=0,c=0;int direction=0;for(const auto& point:path){if(point.first!=r||point.second!=c||seen[r][c])return false;seen[r][c]=true;long long nr=static_cast<long long>(r)+dr[direction],nc=static_cast<long long>(c)+dc[direction];if(nr<0||nc<0||nr>=static_cast<long long>(rows)||nc>=static_cast<long long>(columns)||seen[static_cast<std::size_t>(nr)][static_cast<std::size_t>(nc)]){direction=(direction+1)%4;nr=static_cast<long long>(r)+dr[direction];nc=static_cast<long long>(c)+dc[direction];}r=static_cast<std::size_t>(nr);c=static_cast<std::size_t>(nc);}return true;}
